"""Validated original generated bytes, separate from a source-pixel mask."""
import io
from dataclasses import dataclass

from PIL import Image
from extractor_core.io import MAX_BYTES, read_image, png_bytes
from .base import ProviderError


@dataclass(frozen=True)
class GeneratedImage:
    data: bytes
    image: Image.Image
    extension: str
    media_type: str
    transparent: bool

    @classmethod
    def decode(cls, data):
        if not isinstance(data, bytes) or not data or len(data) > MAX_BYTES:
            raise ProviderError("没有取得有效图像文件；请核对用量，不会自动重试")
        try:
            with Image.open(io.BytesIO(data)) as probe:
                kind = probe.format
                alpha_present = "A" in probe.getbands() or "transparency" in probe.info
            image = read_image(data)
            extension, media = {"PNG": ("png", "image/png"), "JPEG": ("jpg", "image/jpeg"),
                                "WEBP": ("webp", "image/webp")}[kind]
        except (ValueError, OSError, SyntaxError, KeyError):
            raise ProviderError("生成结果不是有效的 PNG、JPG 或 WebP；原工作图已保留") from None
        low, high = image.getchannel("A").getextrema()
        if high == 0:
            raise ProviderError("生成结果完全透明，没有可用图案")
        return cls(data, image, extension, media, kind == "PNG" and alpha_present and low == 0)

    @classmethod
    def from_image(cls, image):
        return cls.decode(png_bytes(image))

    def public(self):
        alpha = self.image.getchannel("A")
        low, high = alpha.getextrema()
        return {"width": self.image.width, "height": self.image.height, "format": self.extension,
                "media_type": self.media_type, "transparent": self.transparent,
                "needs_background_removal": not self.transparent, "alpha_min": low, "alpha_max": high,
                "transparent_fraction": alpha.histogram()[0] / (self.image.width * self.image.height)}
